// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract PayProof {
    address public immutable arbitrator;

    enum Status {
        PaymentRecorded,
        Disputed,
        Refunded,
        RefundRejected
    }

    struct Payment {
        uint256 id;
        address customer;
        address merchant;
        uint256 amount;
        Status status;
        bytes32 evidenceHash;
        string merchantResponse;
    }

    uint256 public nextPaymentId = 1;

    mapping(uint256 => Payment) public payments;

    event PaymentCreated(
        uint256 indexed paymentId,
        address indexed customer,
        address indexed merchant,
        uint256 amount
    );

    event DisputeOpened(
        uint256 indexed paymentId,
        bytes32 evidenceHash
    );

    event MerchantResponded(
        uint256 indexed paymentId,
        string response
    );

    event DisputeResolved(
        uint256 indexed paymentId,
        bool refundApproved
    );

    constructor() {
        arbitrator = msg.sender;
    }

    modifier onlyArbitrator() {
        require(
            msg.sender == arbitrator,
            "Only arbitrator can perform this action"
        );
        _;
    }

    function createPayment(
        address merchant,
        uint256 amount
    ) external returns (uint256) {
        require(merchant != address(0), "Invalid merchant");
        require(merchant != msg.sender, "Customer cannot be merchant");
        require(amount > 0, "Amount must be greater than zero");

        uint256 paymentId = nextPaymentId++;

        payments[paymentId] = Payment({
            id: paymentId,
            customer: msg.sender,
            merchant: merchant,
            amount: amount,
            status: Status.PaymentRecorded,
            evidenceHash: bytes32(0),
            merchantResponse: ""
        });

        emit PaymentCreated(
            paymentId,
            msg.sender,
            merchant,
            amount
        );

        return paymentId;
    }

    function openDispute(
        uint256 paymentId,
        bytes32 evidenceHash
    ) external {
        Payment storage payment = payments[paymentId];

        require(payment.id != 0, "Payment does not exist");
        require(msg.sender == payment.customer, "Only customer");
        require(
            payment.status == Status.PaymentRecorded,
            "Payment cannot be disputed"
        );
        require(
            evidenceHash != bytes32(0),
            "Evidence hash required"
        );

        payment.status = Status.Disputed;
        payment.evidenceHash = evidenceHash;

        emit DisputeOpened(paymentId, evidenceHash);
    }

    function merchantRespond(
        uint256 paymentId,
        string calldata response
    ) external {
        Payment storage payment = payments[paymentId];

        require(payment.id != 0, "Payment does not exist");
        require(msg.sender == payment.merchant, "Only merchant");
        require(
            payment.status == Status.Disputed,
            "No active dispute"
        );
        require(bytes(response).length > 0, "Response required");

        payment.merchantResponse = response;

        emit MerchantResponded(paymentId, response);
    }

    function resolveDispute(
        uint256 paymentId,
        bool refundApproved
    ) external onlyArbitrator {
        Payment storage payment = payments[paymentId];

        require(payment.id != 0, "Payment does not exist");
        require(
            payment.status == Status.Disputed,
            "Payment is not disputed"
        );

        if (refundApproved) {
            payment.status = Status.Refunded;
        } else {
            payment.status = Status.RefundRejected;
        }

        emit DisputeResolved(paymentId, refundApproved);
    }

    function getPayment(
        uint256 paymentId
    ) external view returns (Payment memory) {
        require(
            payments[paymentId].id != 0,
            "Payment does not exist"
        );

        return payments[paymentId];
    }
}
